mapper.select:

SELECT p.*, b.name AS building_name, b.zone AS building_zone, , 
FROM products p
LEFT JOIN buildings b ON b.id = p.building_id
WHERE (p.status <> '已下架' OR p.seller_id = #{uid,javaType=java.util.UUID,jdbcType=OTHER})
  AND 
AND p.category = #{category}
AND p.campus = #{campus}
AND p.condition = #{condition}
AND (p.title ILIKE CONCAT('%', #{keyword}, '%') OR p.description ILIKE CONCAT('%', #{keyword}, '%'))
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
ORDER BY ${orderBy}, p.id
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM products p
WHERE (p.status <> '已下架' OR p.seller_id = #{uid,javaType=java.util.UUID,jdbcType=OTHER})
  AND 
AND p.category = #{category}
AND p.campus = #{campus}
AND p.condition = #{condition}
AND (p.title ILIKE CONCAT('%', #{keyword}, '%') OR p.description ILIKE CONCAT('%', #{keyword}, '%'))
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}

