title = #{title}, description = #{description}, price = #{price}, original_price = #{originalPrice,jdbcType=NUMERIC}, category = #{category}, condition = #{condition}, campus = #{campus}, images = #{images,typeHandler=com.lulu.campusmarketbackend.mapper.JsonbTypeHandler}, contact = #{contact}, building_id = #{buildingId,jdbcType=VARCHAR}, status = #{status}, sold_at = #{soldAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
WHERE id = #{id}

